using JobOrbit.Application.DTOs.AdminDepartments;using JobOrbit.Application.Interfaces;namespace JobOrbit.Application.Services;public sealed class AdminDepartmentService(IAdminDepartmentRepository repo):IAdminDepartmentService{public Task<AdminDepartmentListResult>ListAsync(AdminDepartmentQuery q,CancellationToken t=default)=>repo.ListAsync(q,t);public Task<AdminDepartmentDetailsDto?>DetailsAsync(int id,CancellationToken t=default)=>repo.DetailsAsync(id,t);public Task<IReadOnlyList<DepartmentLookupDto>>LookupAsync(int org,bool inactive,CancellationToken t=default)=>repo.LookupAsync(org,inactive,t);public Task<AdminDepartmentResult>CreateAsync(int admin,CreateDepartmentRequest r,CancellationToken t=default)=>repo.CreateAsync(admin,r,t);public Task<AdminDepartmentResult>UpdateAsync(int admin,int id,UpdateDepartmentRequest r,CancellationToken t=default)=>repo.UpdateAsync(admin,id,r,t);public Task<AdminDepartmentResult>StatusAsync(int admin,int id,UpdateDepartmentStatusRequest r,CancellationToken t=default)=>repo.StatusAsync(admin,id,r,t);}
